mapper.select:
SELECT *
FROM bbx_work_order
WHERE deleted = 1

    AND tenant_id = #{param.tenantId}


    AND code LIKE CONCAT('%', #{param.code}, '%')


    AND dispatch_type = #{param.dispatchType}


    AND name LIKE CONCAT('%', #{param.name}, '%')


    AND allot_uname LIKE CONCAT('%', #{param.allotUname}, '%')


    AND processed_person_name LIKE CONCAT('%', #{param.processedPersonName}, '%')


    AND status = #{param.status}


    AND FIND_IN_SET(#{param.spaceId}, REPLACE(space_id, '|', ',')) > 0


    AND source = #{param.source}


    AND create_time >= #{param.startTime}


    AND create_time <= #{param.endTime}


    AND (id in (select DISTINCT(work_id) from bbx_work_schedule_user where user_id = #{param.creatorId}) or (status in (40,50) and audit_uid = #{param.creatorId}))


    AND out_status = #{param.outStatus}


    AND transfer_uid IS NOT NULL


    AND transfer_uid IS NULL


    AND (id in (SELECT DISTINCT work_order_id FROM bbx_work_order_device WHERE device_id IN

        #{deviceId}

    )
    OR id in (SELECT DISTINCT work_id FROM bbx_work_task  WHERE business_type IN (1,4) AND business_id IN

        #{deviceId}

    ))



ORDER BY create_time DESC

SELECT ROUND(AVG(expend_time), 1) AS averageExpendTime
FROM bbx_work_order
WHERE processed_person_id = #{processedPersonId}
  AND expend_time IS NOT NULL
  AND deleted = 1
  AND status = #{completedStatus}

SELECT COUNT(*) AS totalNum,
COALESCE(SUM(CASE WHEN status = 50 THEN 1 ELSE 0 END),0) AS finishNum,
(
SELECT source
FROM bbx_work_order
where deleted = 1 and (id in
(SELECT DISTINCT work_order_id from bbx_work_order_device


        device_id =#{condition.deviceId}


        and tenant_id =#{condition.tenantId}


)
OR id in (SELECT DISTINCT work_id FROM bbx_work_task  WHERE business_type IN (1,4)

        AND business_id =#{condition.deviceId}


        and tenant_id =#{condition.tenantId}

)
)
GROUP BY source ORDER BY COUNT(*) DESC LIMIT 1) AS source,
(
SELECT COUNT(*)
FROM bbx_work_order
where deleted = 1 and id in
(SELECT DISTINCT work_order_id from bbx_work_order_device


        device_id =#{condition.deviceId}


        and tenant_id =#{condition.tenantId}

)
GROUP BY source ORDER BY COUNT(*) DESC LIMIT 1) AS sourceNum
FROM bbx_work_order
where deleted = 1 and id in
(SELECT DISTINCT work_order_id from bbx_work_order_device


        device_id =#{condition.deviceId}


        and tenant_id =#{condition.tenantId}

)

SELECT name, totalNum, ROUND(totalNum * 100.0 / SUM(totalNum) OVER(), 2) AS numRate FROM ( SELECT CASE WHEN source IN ('meterPlan', 'maintainPlan', 'inspectionPlan', 'patrolPlan', 'inventoryPlan') THEN '合同计划' WHEN source = 'person' THEN '报事报修' WHEN source = 'alarm' THEN '设备告警' WHEN source = 'taskPlan' THEN '业主任务' ELSE COALESCE(source, '未知来源') END AS name, COUNT(*) AS totalNum FROM bbx_work_order WHERE deleted = 1
and tenant_id =#{tenantId}
GROUP BY CASE WHEN source IN ('meterPlan', 'maintainPlan', 'inspectionPlan', 'patrolPlan', 'inventoryPlan') THEN '合同计划' WHEN source = 'person' THEN '报事报修' WHEN source = 'alarm' THEN '设备告警' WHEN source = 'taskPlan' THEN '业主任务' ELSE COALESCE(source, '未知来源') END ) AS source_stats

SELECT CASE WHEN source = 'meterPlan' THEN '抄表计划' WHEN source = 'maintainPlan' THEN '维保计划' WHEN source = 'inspectionPlan' THEN '巡检计划' WHEN source = 'patrolPlan' THEN '巡更计划' WHEN source = 'inventoryPlan' THEN '盘点计划' ELSE '未知计划类型' END AS name, COUNT(CASE WHEN error_status == 1 THEN 1 END) AS errorNum, COUNT(CASE WHEN error_status == 0 THEN 1 END) AS noErrorNum FROM bbx_work_order WHERE deleted = 1 and status = 50
and tenant_id =#{tenantId}
AND source IN ('meterPlan', 'maintainPlan', 'inspectionPlan', 'patrolPlan', 'inventoryPlan') GROUP BY source ORDER BY CASE WHEN source = 'meterPlan' THEN 1 WHEN source = 'maintainPlan' THEN 2 WHEN source = 'inspectionPlan' THEN 3 WHEN source = 'patrolPlan' THEN 4 WHEN source = 'inventoryPlan' THEN 5 ELSE 6 END

SELECT TO_CHAR(TRUNC(end_time), 'MM-dd') AS time, COUNT(*) AS totalNum FROM bbx_work_order WHERE deleted = 1
and tenant_id =#{tenantId}
AND status = 50 AND end_time >= DATEADD(DAY, -29, SYSDATE) AND end_time <= SYSDATE GROUP BY TRUNC(end_time)

SELECT TO_CHAR(TRUNC(create_time), 'MM-dd') AS time, ROUND(AVG(score), 2) AS avgScore FROM bbx_work_evaluate WHERE deleted = 1
and tenant_id =#{tenantId}
and create_time >= DATEADD(DAY, -29, SYSDATE) AND create_time <= SYSDATE GROUP BY TRUNC(create_time);

SELECT CASE WHEN w.source IN ('meterPlan', 'maintainPlan', 'inspectionPlan', 'patrolPlan', 'inventoryPlan') THEN '合同计划' WHEN w.source = 'person' THEN '报事报修' WHEN w.source = 'alarm' THEN '设备告警' WHEN w.source = 'taskPlan' THEN '业主任务' ELSE COALESCE(w.source, '未知来源') END AS name, w.source, COALESCE(w.department_name, '其他') AS departmentName, COALESCE(w.department_id, '其他') AS departmentId, COUNT(DISTINCT w.id) AS totalNum FROM bbx_work_order w LEFT JOIN ( SELECT work_id, AVG(score) AS avg_score FROM bbx_work_evaluate GROUP BY work_id ) e ON w.id = e.work_id WHERE e.avg_score <= 3 AND e.avg_score IS NOT NULL AND w.deleted = 1
and tenant_id =#{tenantId}
GROUP BY CASE WHEN w.source IN ('meterPlan', 'maintainPlan', 'inspectionPlan', 'patrolPlan', 'inventoryPlan') THEN '合同计划' WHEN w.source = 'person' THEN '报事报修' WHEN w.source = 'alarm' THEN '设备告警' WHEN w.source = 'taskPlan' THEN '业主任务' ELSE COALESCE(w.source, '未知来源') END, w.department_id,w.department_name

SELECT e.*, w.code AS workCode FROM bbx_work_evaluate e INNER JOIN bbx_work_order w ON e.work_id = w.id INNER JOIN ( SELECT work_id, AVG(score) AS avg_score FROM bbx_work_evaluate GROUP BY work_id HAVING avg_score <= 3 ) unsatisfied ON e.work_id = unsatisfied.work_id WHERE w.deleted = 1
and w.tenant_id =#{param.tenantId}
and w.department_id =#{param.departmentId}
and w.source =#{param.source}
AND w.source in
#{source}

SELECT CAST(space_id AS BIGINT) AS id, CASE WHEN source = 'person' THEN '报事报修' WHEN source = 'alarm' THEN '设备告警' ELSE COALESCE(source, '未知来源') END AS name, COUNT(*) AS totalNum FROM bbx_work_order WHERE space_id IS NOT NULL AND REGEXP_LIKE(space_id, '^[0-9]+$') AND deleted = 1
and tenant_id =#{tenantId}
AND source in ('person', 'alarm') GROUP BY space_id, source ORDER BY CASE WHEN source = 'person' THEN 1 WHEN source = 'alarm' THEN 2 ELSE 3 END

SELECT DISTINCT CAST(space_id AS BIGINT) AS space_id FROM bbx_work_order WHERE space_id IS NOT NULL AND deleted = 1
and tenant_id =#{tenantId}
AND source in ('person', 'alarm') AND REGEXP_LIKE(space_id, '^[0-9]+$')

SELECT CASE WHEN w.source IN ('meterPlan', 'maintainPlan', 'inspectionPlan', 'patrolPlan', 'inventoryPlan') THEN '合同计划' WHEN w.source = 'person' THEN '报事报修' WHEN w.source = 'alarm' THEN '设备告警' WHEN w.source = 'taskPlan' THEN '业主任务' ELSE '其他来源' END AS name, SUM(m.material_use_num) AS totalNum FROM bbx_work_order w INNER JOIN bbx_work_material m ON w.id = m.work_id WHERE w.source IS NOT NULL AND w.deleted = 1
and w.tenant_id =#{tenantId}
AND m.material_use_num IS NOT NULL GROUP BY CASE WHEN w.source IN ('meterPlan', 'maintainPlan', 'inspectionPlan', 'patrolPlan', 'inventoryPlan') THEN '合同计划' WHEN w.source = 'person' THEN '报事报修' WHEN w.source = 'alarm' THEN '设备告警' WHEN w.source = 'taskPlan' THEN '业主任务' ELSE '其他来源' END

SELECT DISTINCT wod.device_id FROM bbx_work_order_device wod LEFT JOIN bbx_work_order wo ON wo.id = wod.work_order_id WHERE wo.deleted = 1
and wo.tenant_id =#{tenantId}
AND wo.status != 50 AND wo.source = 'person'

WITH week_dates AS ( SELECT TRUNC(SYSDATE, 'IW') - 1 + (LEVEL - 1) AS day_date FROM DUAL CONNECT BY LEVEL <= 7 )
SELECT w.day_date AS date, COALESCE(COUNT(DISTINCT wo.id), 0) AS count FROM week_dates w LEFT JOIN bbx_work_order wo ON TRUNC(wo.create_time) = w.day_date
AND wo.type IN
#{type}
AND wo.tenant_id = #{tenantId}
AND wo.deleted = 1 -- 只有当满足设备/空间筛选条件时才需要关联设备表，否则直接基于 wo.space_id 判断 AND ( -- 条件1：工单自身的 space_id 在传入的空间集合中
FIND_IN_SET(#{sid},REPLACE(wo.space_id,'|',',')) > 0
OR
-- 条件2：工单关联的设备在传入的设备集合中（需要 EXISTS 子查询）
EXISTS ( SELECT 1 FROM bbx_work_order_device wod WHERE wod.work_order_id = wo.id AND wod.device_id IN
#{did}
AND wod.tenant_id = #{tenantId}
AND wod.deleted = 1 )
1 = 0
) GROUP BY w.day_date ORDER BY w.day_date
